HelpLocalData = {}
HelpLocalData.tab = {
[1001] = {1001, 1, "戰鬥方式", 1, "作為領航雖然不直接參與戰鬥，但在作戰前需要進行<color=#ffbe32>出戰駕駛員</color>的配置。\n在完成駕駛員配置後，點擊“<color=#ffbe32>作戰開始</color>”就會開始戰鬥。", "0", 2},
[1002] = {1002, 1, "配置單位", 2, "在作戰準備時將駕駛員<color=#ffbe32>拖動至戰場上</color>便可完成配置。\n完成配置後可通過“<color=#ffbe32>存儲</color>”按鈕進行保存以便下次直接讀取。", "0", 3},
[1003] = {1003, 1, "行動順序", 3, "每當單位<color=#ffbe32>進行攻擊後</color>便會輪到對方的下一名單位進行行動。\n如果支援型單位進行<color=#ffbe32>支援</color>行動或火力型角色進行<color=#ffbe32>蓄力</color>行動，則會立刻由<color=#ffbe32>同陣營</color>的下一名角色行動，直至進行了攻擊行動後才會輪到對方下一個單位行動。", "sdcg_zszd2", 4},
[1004] = {1004, 1, "行動順序調整", 4, "在作戰準備時點擊<color=#ffbe32>順序調整</color>可以改變隊伍中駕駛員的行動順序。", "0", 5},
[1005] = {1005, 1, "駕駛員類型", 5, "駕駛員分為四種類型。\n<color=#ffbe32>攻擊型</color>——擅長持續輸出。\n<color=#ffbe32>防衛型</color>——擅長保護友軍。\n<color=#ffbe32>支援型</color>——能夠支援隊友，但是自身不參與進攻。\n<color=#ffbe32>火力型</color>——擁有強力武裝但需要在攻擊前進行一回合的蓄力。", "sdcg_jc1", 6},
[1006] = {1006, 1, "攻擊型特徵", 6, "<color=#ffbe32>攻擊型</color>單位每次行動都會進行攻擊，擅長進行持續輸出。", "0", 7},
[1007] = {1007, 1, "防衛型特徵", 7, "<color=#ffbe32>防衛型</color>單位每次行動都會進行攻擊，擅長保護友軍、承受傷害。", "0", 8},
[1008] = {1008, 1, "火力型特徵", 8, "<color=#ffbe32>火力型</color>單位在攻擊前若未處於蓄力完成狀態，則此次行動會被<color=#ffbe32>蓄力</color>動作替代，並且行動順序立刻輪到<color=#ffbe32>同陣營</color>下一名單位。若攻擊前已經處於蓄力完成狀態，則會正常進行攻擊。", "sdcg_zszd1", 9},
[1009] = {1009, 1, "支援型特徵", 9, "<color=#ffbe32>支援型</color>單位不會進行攻擊，支援行動選取的<color=#ffbe32>主要目標</color>為同陣營自身後一位順序的單位，並且行動順序立刻輪到<color=#ffbe32>同陣營</color>下一名單位。", "0", 10},
[1010] = {1010, 1, "攻擊範圍", 10, "每名角色有不同的攻擊範圍，攻擊範圍中的白色格為<color=#ffbe32>主要目標</color>，其餘格子為<color=#ffbe32>次要目標</color>。", "0", 11},
[1011] = {1011, 1, "回避範圍攻擊", 11, "在面對範圍攻擊時可以通過將被攻擊單位之外的<color=#ffbe32>其餘單位</color>配置在對方的<color=#ffbe32>攻擊範圍外</color>進行回避。", "0", 12},
[1012] = {1012, 1, "攻擊目標選取", 12, "支援型單位的支援目標為自身下一位行動的友軍。\n攻擊型、防衛型、火力型的攻擊目標選取規則分為“<color=#ffbe32>最前面</color>”、“<color=#ffbe32>跳過</color>”、“<color=#ffbe32>最後面</color>”。\n“<color=#ffbe32>最前面</color>”——優先攻擊同排的第一名敵人。\n“<color=#ffbe32>跳過</color>”——優先攻擊同排的第二名敵人。\n“<color=#ffbe32>最後面</color>”——優先攻擊同排的最後一名敵人。", "sdcg_zszd3", 13},
[1013] = {1013, 1, "攻擊上排目標", 13, "<color=#ffbe32>同排不存在敵人</color>時會優先攻擊自身所處排的<color=#ffbe32>上一排</color>敵人。若單位自身所處的是最上排，同排無敵人時則會優先攻擊最下排的敵人。", "sdcg_zszd4", 14},
[1014] = {1014, 1, "閃避直擊", 14, "<color=#ffbe32>機動力</color>越高越容易觸發<color=#ffbe32>閃避直擊</color>。\n觸發閃避直擊時，受到的該次傷害會降低百分之35。並且因此次攻擊陷入的負面狀態的持續時間也會減半。", "0", 15},
[1015] = {1015, 1, "查看情報", 15, "在<color=#ffbe32>作戰準備</color>時點擊敵方或者友軍單位就能查看對應單位的<color=#ffbe32>情報</color>。", "0", 16},
[1016] = {1016, 1, "回合與輪次", 16, "每當有一名單位結束行動時，便視為經過一<color=#ffbe32>回合</color>。當所有單位都進行過一次行動時則視為經過一<color=#ffbe32>輪</color>。", "0", 17},
[1017] = {1017, 1, "勝敗條件", 17, "當有一方所有單位都<color=#ffbe32>無法戰鬥</color>時則<color=#ffbe32>作戰結束</color>，還有單位處於戰鬥可能狀態的一方獲勝。此外，如果有一方<color=#ffbe32>只剩支援型</color>單位處於戰鬥可能狀態，則也視為<color=#ffbe32>作戰失敗</color>。", "sdcg_zszd6", 18},
[1018] = {1018, 1, "狂暴", 18, "當作戰輪數超過十輪，所有單位都會進入<color=#ffbe32>狂暴</color>狀態。進入狂暴狀態的單位傷害會提高，且駕駛員與敵人會受到負面效果影響（所有boss類型敵人不受負面效果影響）。\n此外，隨著輪數的增加，狂暴的層數也會隨之增加。", "0", 19},
[1019] = {1019, 1, "作戰自動結束", 19, "當作戰進行到<color=#ffbe32>十五輪</color>後會直接顯示作戰結果，若<color=#ffbe32>五十輪</color>仍未分出勝負則視作<color=#ffbe32>進攻方獲勝</color>。", "0", 20},
[1020] = {1020, 1, "高威脅單位", 20, "初次遭遇某些特殊原罪時，會有<color=#ffbe32>高威脅單位</color>的提示框彈出。\n注意並瞭解這些原罪，及時作出應對，能更為有效的進行戰鬥。", "sdcg_gwxdw", 21},
[2001] = {2001, 2, "駕駛員技能", 1, "每名駕駛員都持有不同的<color=#ffbe32>技能</color>。滿足觸發條件後便會自動使用。", "0", 22},
[2002] = {2002, 2, "技能類型", 2, "技能分為多種<color=#ffbe32>類型</color>，不同類型各自有不同種類的效果。", "0", 23},
[2003] = {2003, 2, "觸發條件", 3, "技能的<color=#ffbe32>觸發條件</color>各有不同，例如戰鬥開始前，支援時等。滿足觸發條件便會自動使用。", "0", 24},
[2004] = {2004, 2, "持續時間", 4, "技能有不同的<color=#ffbe32>持續時間</color>。\n主要分為三種。永久生效的“<color=#ffbe32>永久</color>”，持續一定回合數的“<color=#ffbe32>回</color>”，以及立刻生效不持續的“<color=#ffbe32>立即</color>”。", "0", 25},
[2005] = {2005, 2, "技能對象", 5, "<color=#ffbe32>技能對象</color>決定了技能對哪些目標起效。\n例如給自己附加強化狀態的技能，其技能對象便是自己。", "0", 26},
[2006] = {2006, 2, "例外事項", 6, "<color=#ffbe32>例外事項</color>中記述了技能的特殊判定機制，當技能之間有所衝突時，判定會以例外事項中記述的條目<color=#ffbe32>優先</color>。", "0", 27},
[2007] = {2007, 2, "增益技能", 7, "<color=#ffbe32>增益技能</color>中包含各種會給自己增加不同種類增益效果的技能。", "0", 28},
[2008] = {2008, 2, "減益技能", 8, "<color=#ffbe32>負面技能</color>中包含各種會給敵人施加不同種類減益效果的技能。", "sdcg_zszd7", 29},
[2009] = {2009, 2, "主要目標", 9, "<color=#ffbe32>主要目標</color>是在目標選取規則下，自身攻擊範圍內<color=#ffbe32>第一個</color>進行判定的單位。", "0", 30},
[2010] = {2010, 2, "固定傷害/真實傷害", 10, "<color=#ffbe32>固定傷害</color>不會受到任何裝甲值，機動力，減傷技能和致命率的影響。如果攻擊對象有護盾值，則會優先削減護盾值。\n<color=#ffbe32>真實傷害</color>不會受到裝甲值，機動力和減傷技能的影響，能夠觸發致命攻擊，並且會穿透護盾值直接減少攻擊對象的生命值。", "0", 31},
[2011] = {2011, 2, "傷害類", 11, "<color=#ffbe32>傷害類</color>技能會使攻擊造成額外的傷害。", "0", 32},
[2012] = {2012, 2, "免疫類", 12, "<color=#ffbe32>免疫類</color>技能能夠使單位不受特定種類技能的影響。", "sdcg_zszd9", 33},
[2013] = {2013, 2, "重置類", 13, "<color=#ffbe32>重置類</color>技能包含能夠刷新單位自身狀態及技能持續時間等效果的技能。", "0", 34},
[2014] = {2014, 2, "反射類", 14, "<color=#ffbe32>反射類</color>技能能夠在單位受到攻擊時對敵人造成傷害。", "0", 35},
[2015] = {2015, 2, "復活類", 15, "<color=#ffbe32>復活類</color>技能能夠在戰鬥中讓處於無法戰鬥的隊友重新變為戰鬥可能狀態。", "0", 36},
[2016] = {2016, 2, "恢復類", 16, "<color=#ffbe32>恢復類</color>技能包含各種直接恢復生命值或在滿足條件時恢復生命值的技能。", "0", 37},
[2017] = {2017, 2, "持續傷害類", 17, "<color=#ffbe32>持續傷害類</color>技能能夠在持續時間內每回合都對目標造成傷害。\n“<color=#ffbe32>毒素</color>”類的持續傷害會直接減少對象的生命值上限，在被驅散或持續時間結束後生命值上限會恢復到原本數值，但是扣除的生命值本身不會恢復。", "sdcg_zszd14", 38},
[2018] = {2018, 2, "嘲諷類", 18, "<color=#ffbe32>嘲諷類</color>技能能夠在技能的持續時間內讓敵人的攻擊集中在使用者身上。", "sdcg_zszd11", 39},
[2019] = {2019, 2, "控制類", 19, "<color=#ffbe32>控制類</color>技能包含讓敵人無法行動的技能。", "0", 40},
[2020] = {2020, 2, "專注類", 20, "<color=#ffbe32>專注類</color>技能能夠使單位不受對方嘲諷類技能的影響。", "0", 41},
[2021] = {2021, 2, "禁止類", 21, "<color=#ffbe32>禁止類</color>技能能讓目標無法受到對應種類技能的效果。", "0", 42},
[2022] = {2022, 2, "弱化類", 22, "<color=#ffbe32>弱化類</color>技能會對目標造成各種能力值減益效果。", "sdcg_zszd8", 43},
[2023] = {2023, 2, "強化類", 23, "<color=#ffbe32>強化類</color>技能能夠讓目標獲得各種增益效果。", "0", 44},
[2024] = {2024, 2, "複製/掠奪類", 24, "<color=#ffbe32>複製/掠奪類</color>技能能夠從目標對象上獲得強化效果對自身進行強化。", "0", 45},
[2025] = {2025, 2, "驅散類", 25, "<color=#ffbe32>驅散類</color>技能能夠解除目標單位身上的增益或減益效果。", "0", 46},
[2026] = {2026, 2, "護盾類", 26, "<color=#ffbe32>護盾類</color>技能能夠產生護盾，在受到傷害時會優先以護盾值代替生命值進行扣除。", "0", 47},
[2027] = {2027, 2, "賦予類", 27, "<color=#ffbe32>賦予類</color>技能能夠給目標施加各種不同種類的額外效果。", "0", 48},
[2028] = {2028, 2, "傷害減免類", 28, "<color=#ffbe32>傷害減免類</color>技能能夠降低使用者受到的傷害。", "0", 49},
[2029] = {2029, 2, "集火類", 29, "<color=#ffbe32>集火類</color>技能能夠在持續時間內讓友軍的攻擊集中在技能使用者攻擊的主要目標上。", "0", 50},
[2030] = {2030, 2, "特殊類", 30, "<color=#ffbe32>特殊類</color>技能包含非常規的技能效果。例如能夠使火力型單位不需要進行蓄力等。", "0", 51},
[2031] = {2031, 2, "反擊類", 31, "<color=#ffbe32>反擊類</color>技能能夠在使用者受到攻擊後，向攻擊者進行反擊。", "0", 52},
[2032] = {2032, 2, "犧牲類", 32, "持有<color=#ffbe32>犧牲類</color>技能的單位能夠在友軍受到致死攻擊時，將友軍維持在戰鬥可能的狀態。", "0", 53},
[2033] = {2033, 2, "免死類", 33, "<color=#ffbe32>免死類</color>技能能夠使對象在持續時間內不會進入戰鬥不能狀態。", "0", 54},
[2034] = {2034, 2, "魅惑類", 34, "<color=#ffbe32>魅惑類</color>技能能讓目標在持續時間內以友軍為攻擊對象進行攻擊。", "0", 0},
[2035] = {2035, 2, "EX技能", 35, "<color=#ffbe32>EX技能</color>是3星的駕駛員入隊時自帶的額外技能。在戰鬥中滿足條件就會自動釋放，擁有自身獨立的5輪冷卻時間。", "0", 55},
[2036] = {2036, 2, "最大生命值", 36, "在計算以己方或敵方<color=#ffbe32>最大生命值</color>為條件的技能傷害時，最大生命值的取值是有上限的，最高可取值為4萬。", "0", 56},
[2037] = {2037, 2, "效果數量", 37, "在計算以己方或敵方身上的<color=#ffbe32>效果數量</color>為條件的技能傷害時，效果數量的取值是有上限的，最高可取值為5。", "0", 57},
[2038] = {2038, 2, "免疫", 38, "免疫分為<color=#ffbe32>一級免疫</color>與<color=#ffbe32>二級免疫</color>。\n<color=#ffbe32>一級免疫</color>包含免疫魅惑、免疫控制、免疫弱化、免疫持續的單項免疫。<color=#ffbe32>二級免疫</color>包含免疫所有減益類效果、免疫所有增益類效果的多項免疫。（一級免疫包含在二級免疫當中）", "0", 0},
[2039] = {2039, 2, "無視免疫", 39, "無視免疫分為<color=#ffbe32>無視一級免疫</color>與<color=#ffbe32>無視二級免疫</color>。\n<color=#ffbe32>無視一級免疫</color>可無視相對應的一級免疫效果。<color=#ffbe32>無視二級免疫</color>可無視相對應的二級免疫效果。（無視一級免疫包含在無視二級免疫當中）", "0", 0},
[3001] = {3001, 3, "駕駛員等級", 1, "隨著<color=#ffbe32>駕駛員等級</color>提高，駕駛員的各項基礎能力也會提高。<color=#ffbe32>駕駛員等級</color>可以通過進行消耗體力的作戰或是使用回收資料來提升。", "0", 58},
[3002] = {3002, 3, "生命值", 2, "單位的<color=#ffbe32>生命值</color>歸零就會處於戰鬥不能狀態。", "0", 59},
[3003] = {3003, 3, "攻擊力", 3, "<color=#ffbe32>攻擊力</color>會影響駕駛員造成的傷害，攻擊力越高造成的傷害越高。", "0", 60},
[3004] = {3004, 3, "裝甲值", 4, "<color=#ffbe32>裝甲值</color>能夠減少駕駛員受到的傷害，如果<color=#ffbe32>裝甲值</color>到達百分之百，則傷害就會降低百分之百。這時就需要通過使用<color=#ffbe32>弱化類</color>技能降低目標的裝甲值，或是使用<color=#ffbe32>固定傷害</color>和<color=#ffbe32>真實傷害</color>無視裝甲值造成傷害。", "0", 61},
[3005] = {3005, 3, "致命率", 5, "<color=#ffbe32>致命率</color>決定觸發致命攻擊的幾率。", "0", 62},
[3006] = {3006, 3, "致命傷害", 6, "<color=#ffbe32>致命傷害</color>決定觸發致命攻擊時傷害的提升量。", "0", 63},
[3007] = {3007, 3, "超限致命傷害", 7, "<color=#ffbe32>超限致命傷害</color>決定觸發致命攻擊時傷害的提升量。超限致命傷害不會計入致命傷害的上限。", "0", 132},
[3008] = {3008, 3, "機動力", 8, "<color=#ffbe32>機動力</color>決定觸發閃避直擊的幾率，<color=#ffbe32>機動力</color>越高越容易觸發閃避直擊。\n觸發閃避直擊時能夠減少該次攻擊的百分之35傷害，並且該次攻擊造成的減益狀態的持續時間也會減半。", "sdcg_zszd13", 64},
[3009] = {3009, 3, "護盾效能", 9, "<color=#ffbe32>護盾效能</color>決定獲得護盾時的護盾量。", "0", 115},
[3010] = {3010, 3, "力場防禦", 10, "<color=#ffbe32>力場防禦</color>能夠減少駕駛員受到的傷害，如果<color=#ffbe32>力場防禦</color>到達百分之百，則傷害就會降低百分之百。這時就需要通過使用<color=#ffbe32>弱化類</color>技能降低目標的裝甲值，或是使用<color=#ffbe32>固定傷害</color>和<color=#ffbe32>真實傷害</color>無視力場防禦造成傷害。", "0", 65},
[3011] = {3011, 3, "減傷係數", 11, "<color=#ffbe32>減傷係數</color>能夠減少駕駛員受到的傷害，如果<color=#ffbe32>減傷係數</color>到達百分之百，則傷害就會降低百分之百。這時就需要通過使用<color=#ffbe32>弱化類</color>技能降低目標的減傷係數，或是使用<color=#ffbe32>固定傷害</color>和<color=#ffbe32>真實傷害</color>無視減傷係數造成傷害。", "0", 66},
[3012] = {3012, 3, "額外攻擊", 12, "<color=#ffbe32>額外攻擊</color>能夠提升駕駛員造成的傷害，額外攻擊不會受到機甲核心和共鳴裝備的百分比攻擊增幅。", "0", 67},
[3013] = {3013, 3, "傷害加成", 13, "<color=#ffbe32>傷害加成</color>能夠提升駕駛員造成的傷害，如果<color=#ffbe32>傷害加成</color>到達百分之百，則傷害就會提高百分之百。", "0", 138},
[3014] = {3014, 3, "傷害減免", 14, "<color=#ffbe32>傷害減免</color>能夠減少駕駛員受到的傷害，如果<color=#ffbe32>傷害減免</color>到達百分之百，則傷害就會降低百分之百。", "0", 68},
[3015] = {3015, 3, "傷害增幅", 13, "<color=#ffbe32>傷害增幅</color>能夠提升駕駛員造成的傷害，如果<color=#ffbe32>傷害增幅</color>到達百分之百，則傷害就會提高百分之百。", "0", 139},
[3016] = {3016, 3, "傷害消解", 14, "<color=#ffbe32>傷害消解</color>能夠減少駕駛員受到的傷害，如果<color=#ffbe32>傷害消解</color>到達百分之百，則傷害就會降低百分之百。", "0", 140},
[3017] = {3017, 3, "閃避減傷比例", 15, "<color=#ffbe32>閃避減傷比例</color>決定觸發閃避直擊的後降低的傷害比例，如果<color=#ffbe32>閃避減傷比例</color>到達百分之百，則傷害就會降低百分之百。這時就需要通過使用<color=#ffbe32>弱化類</color>技能降低目標的閃避減傷比例，或是使用<color=#ffbe32>固定傷害</color>和<color=#ffbe32>真實傷害</color>無視力場防禦造成傷害。", "0", 69},
[3018] = {3018, 3, "固傷抵抗", 16, "<color=#ffbe32>固傷抵抗</color>能夠減少駕駛員受到的固定傷害，如果<color=#ffbe32>傷害減免</color>到達百分之百，則固定傷害就會降低百分之百。", "0", 70},
[3019] = {3019, 3, "裝甲穿透", 17, "<color=#ffbe32>装甲穿透</color>能夠提升駕駛員對擁有裝甲值的單位造成的傷害，如果<color=#ffbe32>装甲穿透</color>到達百分之百，則會無視裝甲值造成傷害。", "0", 71},
[3020] = {3020, 3, "閃避穿透", 18, "<color=#ffbe32>閃避穿透</color>能夠提升駕駛員對觸發閃避直擊的單位造成的傷害，如果<color=#ffbe32>閃避穿透</color>到達百分之百，則會無視閃避直擊造成傷害。", "0", 72},
[3021] = {3021, 3, "減傷穿透", 19, "<color=#ffbe32>装甲穿透</color>能夠提升駕駛員對擁有減傷係數的單位造成的傷害，如果<color=#ffbe32>減傷穿透</color>到達百分之百，則會無視減傷係數造成傷害。", "0", 113},
[3022] = {3022, 3, "力場穿透", 20, "<color=#ffbe32>力場穿透</color>能夠提升駕駛員對擁有力場防禦的單位造成的傷害，如果<color=#ffbe32>力場穿透</color>到達百分之百，則會無視力場防禦造成傷害。", "0", 130},
[3023] = {3023, 3, "裝甲抵抗", 21, "<color=#ffbe32>装甲抵抗</color>能夠提升駕駛員對裝甲穿透的抵抗力，可抵消敵人的裝甲穿透效率。", "0", 133},
[3024] = {3024, 3, "閃避抵抗", 22, "<color=#ffbe32>閃避抵抗</color>能夠提升駕駛員對閃避穿透的抵抗力，可抵消敵人的閃避穿透效率。", "0", 134},
[3025] = {3025, 3, "減傷抵抗", 23, "<color=#ffbe32>減傷抵抗</color>能夠提升駕駛員對減傷穿透的抵抗力，可抵消敵人的減傷穿透效率。", "0", 135},
[3026] = {3026, 3, "力場抵抗", 24, "<color=#ffbe32>力場抵抗</color>能夠提升駕駛員對力場穿透的抵抗力，可抵消敵人的力場穿透效率。", "0", 136},
[3027] = {3027, 3, "升級", 25, "<color=#ffbe32>升級</color>能夠提高駕駛員的各項基礎能力，消耗報告資料和盾幣就能進行<color=#ffbe32>升級</color>。", "sdcg_jc2", 118},
[3028] = {3028, 3, "界限突破", 26, "當駕駛員等級達到當前的滿級時，可以消耗幻化星碎和盾幣進行<color=#ffbe32>界限突破</color>。\n<color=#ffbe32>界限突破</color>後駕駛員的等級上限和能力成長會有所提高。星級達到6星時，無法再進行<color=#ffbe32>界限突破</color>。", "sdcg_qzjc2", 119},
[3029] = {3029, 3, "覺醒", 27, "駕駛員進行過一次界限突破後就能夠消耗對應種類的覺醒水晶和盾幣進行<color=#ffbe32>覺醒</color>。<color=#ffbe32>覺醒</color>後駕駛員會提高各項基本能力，並且會解鎖<color=#ffbe32>覺醒技能</color>。", "0", 120},
[3030] = {3030, 3, "技能強化", 28, "通過使用盾幣和駕駛員專屬的【殘響】就能提升駕駛員的技能等級，可通過<color=#ffbe32>技能強化</color>提升的技能等級最高為9級（當駕駛員自身3件共鳴裝備全收集時，技能等級會提高1級。技能等級最高為10級）。", "sdcg_qzjc1", 121},
[3031] = {3031, 3, "機甲核心", 29, "<color=#ffbe32>機甲核心</color>可以提升各項不同的能力值。等級、星級、品質越高，提升的對應能力值越高。", "0", 122},
[3032] = {3032, 3, "機甲核心強化", 30, "消耗盾幣及其他的機甲核心可以進行<color=#ffbe32>強化</color>，提升機甲核心的等級。升級時會在一定範圍內隨機提升能力值（若提升的不是最大值，則可以通過開發提升其能力值。）。\n5星及以上的機甲核心在等級達到滿級時還可以將其<color=#ffbe32>進階</color>成高一級品質的機甲核心，此時機甲核心等級會回到5級，能力成長會提升。\n品質達到5星傳說+滿級時，再次<color=#ffbe32>進階</color>就會變為6星史诗級機甲核心。", "0", 123},
[3033] = {3033, 3, "機甲核心開發", 31, "進行<color=#ffbe32>開發</color>可以提高機甲核心的<color=#ffbe32>開發度</color>。\n<color=#ffbe32>開發度</color>越高機甲核心帶來的能力值提升越高，最高為百分之一百（百分之一百時的數值即為強化升級時每次都隨機出最大值的狀態）。", "0", 124},
[3034] = {3034, 3, "共鳴裝備", 32, "消耗<color=#ffbe32>共鳴原石</color>可以在補給界面中入手<color=#ffbe32>共鳴裝備</color>。重複的<color=#ffbe32>共鳴裝備</color>會自動變化為<color=#ffbe32>共鳴結晶體</color>。\n消耗<color=#ffbe32>共鳴結晶體</color>和盾幣就可以強化共鳴裝備。當駕駛員自身三件<color=#ffbe32>共鳴裝備</color>全收集時，該駕駛員的<color=#ffbe32>技能等級</color>就會提高一級。", "sdcg_qzjc3", 125},
[3035] = {3035, 3, "超限共鳴裝備", 33, "消耗<color=#ffbe32>超越共鳴因子</color>和強力原罪的<color=#ffbe32>尼姆比斯結晶</color>。能夠解鎖駕駛員的<color=#ffbe32>超限共鳴裝備</color>並獲得一次技能強化效果。\n消耗<color=#ffbe32>共鳴結晶體</color>和盾幣可以強化超限共鳴裝備。當駕駛員<color=#ffbe32>超限共鳴裝備</color>達到30級時，該駕駛員將額外獲得一次技能強化效果。", "0", 126},
[4001] = {4001, 4, "郵箱", 1, "<color=#ffbe32>郵箱</color>介面中可以領取系統發送的郵件和獎勵，以及將生日祝福郵件收藏於回憶錄內。", "0", 73},
[4002] = {4002, 4, "設置", 2, "<color=#ffbe32>設置</color>界面中可以調整遊戲內聲音、文本等各項配置。", "0", 74},
[4003] = {4003, 4, "背包", 3, "<color=#ffbe32>背包</color>界面中可以查看持有的道具、機甲核心及共鳴裝備。", "0", 75},
[4004] = {4004, 4, "任務", 4, "<color=#ffbe32>任務</color>界面中可以查看各項任務的完成情況及<color=#ffbe32>活躍積分</color>。\n任務根據刷新時間分為日、週、月三種類型，每種類型都有各自的<color=#ffbe32>活躍積分</color>。完成任務或<color=#ffbe32>活躍積分</color>達到指定數值後就能領取對應的獎勵。", "0", 76},
[4005] = {4005, 4, "圖鑒", 5, "<color=#ffbe32>圖鑒</color>界面中包含角色圖鑒、原罪圖鑒、勛章圖鑒、美術鑒賞、技能圖鑒及成就系統。", "0", 78},
[4006] = {4006, 4, "成就系統", 6, "<color=#ffbe32>成就</color>界面中可以查看各項成就的完成進度。完成成就可以獲得對應的獎勵及勛章。", "0", 77},
[4007] = {4007, 4, "角色圖鑒", 7, "<color=#ffbe32>角色陣營</color>中可以查看各個駕駛員所屬的隊伍及詳細資訊。", "0", 79},
[4008] = {4008, 4, "原罪圖鑒", 8, "<color=#ffbe32>原罪圖鑒</color>中可以查看遊戲中出現的敵方單位的情報。", "0", 80},
[4009] = {4009, 4, "勛章圖鑒", 9, "<color=#ffbe32>勛章圖鑒</color>中可以查看各個勛章的獲取情況及獲取條件。", "0", 81},
[4010] = {4010, 4, "美術鑒賞", 10, "<color=#ffbe32>美術館</color>中可以查看遊戲中出現的插畫、動畫及音樂。", "0", 82},
[4011] = {4011, 4, "技能圖鑒", 11, "<color=#ffbe32>技能圖鑒</color>中可以按照分類查看技能效果，以及持有此技能的駕駛員。", "0", 83},
[4012] = {4012, 4, "商城", 12, "<color=#ffbe32>商城</color>中可以購買各項資源。同時也可以使用獲得的<color=#ffbe32>交換材料</color>兌換不同道具。", "0", 84},
[4013] = {4013, 4, "駕駛員", 13, "<color=#ffbe32>駕駛員</color>界面可以查看自己已經獲得的駕駛員並對她們進行養成。", "0", 85},
[4014] = {4014, 4, "補給", 14, "<color=#ffbe32>補給</color>界面中可以通過消耗調度券或原初結晶徵調新的駕駛員入隊，也可以消耗共鳴原石獲取共鳴裝備。", "0", 86},
[4015] = {4015, 4, "演習", 15, "<color=#ffbe32>演習</color>是駕駛員之間的戰鬥。\n每週為一個新賽季，根據當前賽季中的排名每週結束後會獲得對應的獎勵。\n可挑戰次數會隨著時間恢復，無挑戰次數時可以使用精英演習入場券參加。此外，參加獲得的<color=#ffbe32>精英紀念幣</color>可以在商城兌換各種道具。", "0", 87},
[4016] = {4016, 4, "作戰", 16, "<color=#ffbe32>作戰</color>界面中可以進行各項不同的作戰。包含主線關卡、資源關卡、戰術指導、紅色巨塔、聯合討伐及活動作戰。", "0", 88},
[4017] = {4017, 4, "主線", 17, "<color=#ffbe32>主線</color>中可以體驗劇情遊玩主線關卡。\n根據完成情況每關的評價都分為0星到3星，以3星通過會有額外的獎勵。根據章節整體的星數獲得度也能獲得額外的獎勵。", "0", 89},
[4018] = {4018, 4, "盾幣回收", 18, "<color=#ffbe32>盾幣回收</color>作戰中能夠大量獲得能夠使用在各種地方的盾幣。", "0", 90},
[4019] = {4019, 4, "原罪清剿", 19, "<color=#ffbe32>原罪清剿</color>作戰中能夠大量獲得用以提升駕駛員等級的報告資料。", "0", 91},
[4020] = {4020, 4, "幻化星碎", 20, "<color=#ffbe32>幻化星碎</color>作戰中能夠大量獲得駕駛員用於界限突破的幻化星碎。", "0", 94},
[4021] = {4021, 4, "核心製造", 21, "<color=#ffbe32>核心製造</color>副本中可以大量獲得用以生成機甲核心的<color=#ffbe32>核心碎片</color>，作戰能夠獲得的<color=#ffbe32>核心碎片</color>的種類每天都有所不同。", "0", 92},
[4022] = {4022, 4, "隊員特訓", 22, "<color=#ffbe32>隊員特訓</color>副本中可以大量獲得駕駛員用以覺醒的水晶，每天能夠獲得的<color=#ffbe32>覺醒水晶</color>的種類有所不同。", "0", 93},
[4023] = {4023, 4, "戰術指導", 23, "<color=#ffbe32>戰術指導</color>中可以學習各種作戰的基本戰術，每項指導首次完成時都能獲得獎勵，指導都可以重複觀看，但獎勵只能獲取一次。", "0", 95},
[4024] = {4024, 4, "紅色巨塔", 24, "<color=#ffbe32>紅色巨塔</color>中的關卡設置了諸多挑戰，嘗試挑戰不需要消耗體力，完成一層的關卡後就會解鎖下一層的關卡。關卡設置的每項挑戰首次達成時都會獲得獎勵。隨著樓層的提高，關卡難度也會提高。", "0", 96},
[4025] = {4025, 4, "聯合討伐", 25, "<color=#ffbe32>聯合討伐</color>是討伐強力原罪的作戰。在聯合討伐開啟期間內，每日最多可出擊的次數為三次，每次出擊會獲得積分，積分將會由擊殺分數、回合分數以及傷害分數共同組成。在聯合討伐關閉時，將以玩家最高的單日總積分進行排名，並發放獎勵。", "0", 97},
[4026] = {4026, 4, "個人資訊", 26, "<color=#ffbe32>個人資訊</color>界面可以修改昵稱、問候語、展示紀念勛章及設定副官與能夠給其他領航提供支援的支援駕駛員。", "0", 98},
[4027] = {4027, 4, "好友", 27, "<color=#ffbe32>好友</color>界面可以添加其他玩家為好友，並且可以支援角色、領取好友幣。", "0", 99},
[4028] = {4028, 4, "指揮室", 28, "<color=#ffbe32>指揮室</color>界面可以採集物資，派遣小隊遠征探索資源。", "0", 100},
[4029] = {4029, 4, "活動", 29, "完成<color=#ffbe32>活動</color>關卡和<color=#ffbe32>活動</color>任務可獲取大量活動貨幣，消耗活動貨幣從活動商城購買商品。", "0", 101},
[4030] = {4030, 4, "維護池", 30, "<color=#ffbe32>維護池</color>是幫助駕駛員消解身心疲勞的地方。\n順利完成小遊戲後，說不定可以加深與駕駛員的羈絆。", "0", 102},
[4031] = {4031, 4, "能源工廠", 31, "<color=#ffbe32>能源工廠</color>是生产高级素材的场所\n需要消耗<color=#ffbe32>盾幣</color>和相应的低级素材。", "0", 103},
[4032] = {4032, 4, "裝甲進階", 32, "<color=#ffbe32>裝甲進階</color>作戰中，擊敗曾經遭遇過的強力原罪，能夠獲得用以解鎖超限共鳴裝備的尼姆比斯碎片，後續可在指揮室的能源工廠中合成尼姆比斯結晶。", "0", 112},
[4033] = {4033, 4, "宇宙武道會", 33, "限時開啟：\n1、活動開啟後持續1周，活動期間，每日免費5次，後續挑戰需消耗能源晶體。每天5：00重置挑戰次數。\n2、下次活動開啟時，重置勝利場次記錄、獎勵領取記錄、任務完成記錄、參與隊伍記錄等活動相關資料。\n\n主要玩法：\n1、玩家需要配置進攻和防守兩套陣容，匹配到對手後進行兩輪對戰，第一輪：己方進攻vs對方防守；第二輪：己方防守vs對方進攻，最後得出勝負結果。\n2、勝負確定：戰鬥結束時，根據場上勝利方剩餘駕駛員的血量百分比進行積分計算，若雙方各贏一輪，則根據積分對比，積分高者勝利。\n\n獎勵規則：\n任務獎勵：達成任務條件即可領取。\n排名獎勵：活動結束時，根據排行榜名次，發放對應的名次獎勵。", "0", 114},
[4044] = {4044, 4, "大師賽", 34, "<color=#ffbe32>【注意事项】</color>\n<color=#ffbe32>1、進攻陣容讀取此角色進攻組核心配置，防守陣容讀取此角色防守組核心配置!</color>\n<color=#ffbe32>2、若调整了角色的核心配置，需要重新保存上传才能生效！</color>\n\n【大師賽】整體流程分為【巔峰對決】比賽和【投票】兩部分，以下為【巔峰對決】和【投票】的具體規則：\n\n【巔峰對決】環節規則：\n\n1、【演習】模式中每個賽季總積分前16名的玩家獲得參加【巔峰對決】的資格。（若兩名玩家在4輪常規賽結束後本賽季總積分相同，則根據本賽季常規賽第四輪的排名決定，第四輪排名靠前的獲得更高的賽季排名順位，若兩名玩家常規賽第四輪的排名依舊相同，則比較兩名玩家常規賽第三輪的排名，以此類推）\n\n2、【大師賽】將在每個賽季的第四輪結束後（即四周後，每一周視為一輪）的下一周周一早上5:00開啟，時間上會和下一賽季常規賽的第一輪並行（該期常規賽獲得的積分將計入下一期大師賽統計）。\n\n3、【巔峰對決】賽程分為：16進8、8進4、4進2、決賽（季軍/冠軍賽），四個階段，每天一場。\n\n4、陣容安排：選手需要配置自己的進攻隊伍和防守隊伍（兩隊中不可出現重復駕駛員），並且在每個比賽日的20:30之前確認上傳自己的陣容。\n\n5、比賽日20:30前可調整陣容；未上傳陣容的玩家將直接判負，若兩名玩家都沒有上傳，則對應賽季常規賽積分排名高直接判勝。\n\n6、【巔峰對決】戰鬥分為2局，第1局玩家A進攻隊伍vs玩家B防守隊伍，第2局玩家B進攻隊伍vs玩家A防守隊伍。若雙方各贏1局，計算雙方勝場中存活駕駛員總血量的占比，高者勝出。若依舊相同，常規賽總積分排名高者勝出。\n\n7、當日比賽的結果將在當日的21:00公布。\n\n8、每期大師賽的前3名玩家將進入【名人堂】。\n\n9、【巔峰對決】獎勵：當期所有入選【巔峰對決】的玩家可獲得限定頭像等獎勵，【巔峰對決】前3名的玩家可額外獲得對應名次的限時頭像框（持續到下一屆大師賽結果出爐）\n\n\n【投票】環節規則：\n\n1、【大師賽】開啟後所有玩家（包含參賽者）獲得一定數量的【大師籌碼】。\n\n2、玩家可以使用【大師籌碼】給支持的選手投票（單場對決只能選擇一名玩家投票），參賽者無法給自身所在的場次投票。\n\n3、若支持的選手勝出，該玩家將在當日比賽結束後，獲得雙倍支持數量的【大師籌碼】；若支持的玩家失敗，則會返還1/2的【大師籌碼】。\n\n4、大師賽決賽結束後，玩家所有的【大師籌碼】會轉換成【大師之證】（需要至少參與過一次投票才會進行轉換，若未參與投票則會直接清空）。\n\n5、玩家可使用【大師之證】在對應商店中換取物品，商店會隨【大師賽】開始一起刷新。", "0", 116},
[4045] = {4045, 4, "希望藍圖", 35, "<color=#ffbe32>希望藍圖</color>系統運作後，可使對應駕駛員獲得強大的力量，藍圖系統會根據駕駛員的職業和特長激活對應的屬性，激活藍圖系統需要消耗對應的記憶體、覺醒水晶、幻化星碎等稀有材料。記憶體可通過參與<color=#ffbe32>命運試煉</color>作戰獲得。\n\n命運試煉中，領航需要擊敗來襲的原罪，戰斗中會根據領航小隊造成的傷害總量計算獎勵，根據造成的輸出不同獎勵也會有所變化。單場戰鬥最多進行兩輪，一方失敗或達到最大戰鬥時長後進入結算，同時命運試煉中玩家對原罪釋放技能時，默認原罪血量低於50%，來襲的原罪釋放技能時，也將默認自己血量低於50%。\n<color=#ffbe32>【注意事项】</color>\n以下為最高獎勵對應傷害：\n簡單（需造成100000傷害獲取最高檔獎勵）\n普通（需造成200000傷害獲取最高檔獎勵）\n困難（需造成300000傷害獲取最高檔獎勵）\n專家（需造成500000傷害獲取最高檔獎勵）\n瘋狂（需造成2000000傷害獲取最高檔獎勵）\n地獄（需造成2500000傷害獲取最高檔獎勵）\n末日（需造成3000000傷害獲取最高檔獎勵）", "0", 117},
[5001] = {5001, 5, "領航等級", 1, "隨著<color=#ffbe32>領航等級</color>的提升，體力值上限會有所提升。", "0", 104},
[5002] = {5002, 5, "體力", 2, "大部分作戰都會消耗<color=#ffbe32>體力</color>，在作戰成功時根據消耗的<color=#ffbe32>體力</color>領航會得到對應量的經驗值。", "0", 105},
[5003] = {5003, 5, "經驗值", 3, "每級的<color=#ffbe32>經驗值</color>達到上限後就會升到下一級。隨著等級的提高，<color=#ffbe32>經驗值</color>的上限也會有所提高。", "0", 106},
[5004] = {5004, 5, "活躍積分", 4, "完成任務時會獲得<color=#ffbe32>活躍積分</color>。日、週、月三種類的任務都有對應種類的<color=#ffbe32>活躍積分</color>。當<color=#ffbe32>活躍積分</color>達到一定值後，就能夠領取額外的獎勵。", "0", 107},
[5005] = {5005, 5, "紀念勛章", 5, "完成<color=#ffbe32>成就</color>或每個部隊收集度達到一定程度時就可領取對應的<color=#ffbe32>紀念勛章</color>，<color=#ffbe32>紀念勛章</color>可以展示在個人資訊界面中。", "0", 108},
[5006] = {5006, 5, "肥皂泡泡", 6, "從戰場上回來的駕駛員需要清洗自己的身子，為駕駛員打上肥皂吧！\n觸碰螢幕沿著規劃好的路線前進，能最大效率地利用肥皂。", "0", 109},
[5007] = {5007, 5, "捕捉水生動物", 7, "因為在海洋、河流作戰，原本棲息於此的水生動物，偶爾會掛在駕駛員身上。\n看準時機點擊螢幕，來幫助駕駛員趕走身上的小動物。", "0", 110},
[5008] = {5008, 5, "抉擇！護膚品之謎", 8, "為駕駛員挑選最合適的護膚品，來自不同地區的駕駛員，適用的護膚品也不同。\n答對每道問題，就能為駕駛員選出最合適的那一款。", "0", 111},
}
return HelpLocalData
